import { chartPath, scalePoints } from "../utils/chart";
import { cx } from "../utils/cx";
import type { SVGProps } from "react";

export type SparklineProps = Omit<SVGProps<SVGSVGElement>, "data" | "children"> & {
  data: number[];
  /** Names it for assistive tech; without one the sparkline is decorative. */
  "aria-label"?: string;
  tone?: "accent" | "success" | "danger" | "muted";
  width?: number;
  height?: number;
};

/** A tiny trend line for a stat or a table cell. Server-compatible. */
export function Sparkline({ data, tone = "accent", width = 96, height = 28, className, ...rest }: SparklineProps) {
  const points = scalePoints(data, width, height, 3, Math.min(...data));
  const last = points[points.length - 1];
  const named = Boolean(rest["aria-label"]);
  return (
    <svg
      {...rest}
      viewBox={`0 0 ${width} ${height}`}
      width={width}
      height={height}
      role={named ? "img" : undefined}
      aria-hidden={named ? undefined : true}
      className={cx("hm-sparkline", className)}
      data-tone={tone}
    >
      <path className="hm-sparkline-line" d={chartPath(points, true)} />
      {last ? <circle className="hm-sparkline-dot" cx={last[0]} cy={last[1]} r="2" /> : null}
    </svg>
  );
}
